import { useId, useState } from "react";
import { Button } from "../../components/ui/button";
import { Label } from "../../components/ui/label";
import { useI18n } from "../../i18n/I18nProvider";

/** A passphrase generated by the server, shown once, to copy and hand over in person. */
export function GeneratedPassphrase({
  passphrase,
  handedOver,
  onHandedOverChange,
}: {
  passphrase: string;
  handedOver: boolean;
  onHandedOverChange(value: boolean): void;
}) {
  const { t } = useI18n();
  const id = useId();
  const [copied, setCopied] = useState(false);
  return (
    <div className="grid gap-2" data-testid="passphrase-generated">
      <p className="text-sm text-muted-foreground">{t("users.passphraseShownOnce")}</p>
      <div className="flex flex-wrap items-center gap-2">
        <code className="text-base font-medium" data-testid="passphrase-value">
          {passphrase}
        </code>
        <Button
          type="button"
          variant="secondary"
          data-testid="passphrase-copy"
          onClick={() =>
            void navigator.clipboard.writeText(passphrase).then(
              () => setCopied(true),
              () => setCopied(false),
            )
          }
        >
          {t(copied ? "users.passphraseCopied" : "users.passphraseCopy")}
        </Button>
      </div>
      <div className="flex items-center gap-2">
        <input
          id={`${id}-handed-over`}
          type="checkbox"
          data-testid="passphrase-handed-over"
          checked={handedOver}
          onChange={(event) => onHandedOverChange(event.currentTarget.checked)}
        />
        <Label htmlFor={`${id}-handed-over`}>{t("users.passphraseHandedOver")}</Label>
      </div>
    </div>
  );
}
